class DanDynamicIsland{static instances=[];constructor(element){Object.assign(this,{element:element,dynamicIsland:element.querySelector('.dan-dynamic-island__container'),overlay:element.querySelector('.dan-dynamic-island__overlay'),linksContainer:element.querySelector('.dan-dynamic-island__nav'),progressCircle:element.querySelector('.dan-dynamic-island__progress-bar'),percentageText:element.querySelector('.dan-dynamic-island__percentage'),isOpen:!1,lastInsertedLink:null,animation:null,eventListeners:[],scrollHandler:null});this.config={selector:element.getAttribute('data-selector'),scrollMarginTop:element.getAttribute('data-scroll-margin-top'),expandWidth:element.getAttribute('data-expand-width'),dimensionsDuration:parseFloat(element.getAttribute('data-dimensions-duration')),dimensionsEase:element.getAttribute('data-dimensions-ease'),overlayOpacityDuration:parseFloat(element.getAttribute('data-overlay-opacity-duration')),overlayOpacityEase:element.getAttribute('data-overlay-opacity-ease'),linksContainerOpacityDuration:parseFloat(element.getAttribute('data-links-container-opacity-duration')),linksContainerOpacityEase:element.getAttribute('data-links-container-opacity-ease'),linksWrapperDirection:element.getAttribute('data-links-wrapper-direction')};this.initialize()}
initialize(){if(!this.element.hasAttribute('data-flickering')){return}
this.element.removeAttribute("data-flickering");this.setupInitialValues();this.createAnimation();this.setupEventListeners();this.setupProgressBar();this.setupInitialTabIndex();this.setupKeyboardAccessibility();this.updateClasses(this.isOpen)}
setupInitialValues(){if(this.config.selector){document.querySelectorAll(this.config.selector).forEach(item=>{item.style.scrollMarginTop=this.config.scrollMarginTop});const initialValues=Array.from(document.querySelectorAll(this.config.selector)).map(item=>({title:item.textContent,link:`#${item.id}`}));this.createLinks(initialValues)}}
createLinks(values){const wrapper=this.element.querySelector('.dan-dynamic-island__nav-wrapper');values.forEach(item=>{const link=document.createElement('a');link.href=item.link;link.textContent=item.title;link.className='dan-dynamic-island__link';if(this.config.linksWrapperDirection==='column-reverse'){wrapper.appendChild(link);this.lastInsertedLink=link}else if(this.config.linksWrapperDirection==='column'){if(this.lastInsertedLink){wrapper.insertBefore(link,this.lastInsertedLink.nextSibling)}else{wrapper.insertBefore(link,wrapper.firstChild)}
this.lastInsertedLink=link}})}
createAnimation(){this.animation=gsap.timeline({paused:!0});this.animation.to(this.dynamicIsland,{width:this.config.expandWidth,duration:this.config.dimensionsDuration,ease:this.config.dimensionsEase}).to(this.linksContainer,{height:"auto",duration:this.config.dimensionsDuration,ease:this.config.dimensionsEase},`-=${this.config.dimensionsDuration}`).to(this.overlay,{opacity:1,pointerEvents:"auto",duration:this.config.overlayOpacityDuration,ease:this.config.overlayOpacityEase},`-=${this.config.overlayOpacityDuration}`).to(this.linksContainer,{opacity:1,pointerEvents:"auto",duration:this.config.linksContainerOpacityDuration,ease:this.config.linksContainerOpacityEase},`-=${this.config.linksContainerOpacityDuration}`)}
updateClasses(isOpen){this.dynamicIsland.classList.toggle('open',isOpen);this.dynamicIsland.classList.toggle('close',!isOpen)}
toggleIsland=(open)=>{if(open){this.animation.play();this.dynamicIsland.setAttribute('aria-expanded','true');this.element.querySelectorAll('.dan-dynamic-island__link').forEach(link=>{link.tabIndex=0})}else{this.animation.reverse();this.dynamicIsland.setAttribute('aria-expanded','false');this.element.querySelectorAll('.dan-dynamic-island__link').forEach(link=>{link.tabIndex=-1})}
this.isOpen=open;this.updateClasses(open)}
updateProgress=(animate=!1)=>{const scrollHeight=document.documentElement.scrollHeight-window.innerHeight;const scrollPercentage=Math.min(100,Math.max(0,(window.scrollY/scrollHeight)*100));if(animate){this.progressCircle.classList.add('animate')}else{this.progressCircle.classList.remove('animate')}
this.progressCircle.style.strokeDashoffset=251.2*(1-scrollPercentage/100);this.percentageText.textContent=`${Math.round(scrollPercentage)}%`}
setupProgressBar(){this.updateProgress(!1);setTimeout(()=>{this.scrollHandler=()=>this.updateProgress(!0);window.addEventListener('scroll',this.scrollHandler);this.eventListeners.push({element:window,type:'scroll',handler:this.scrollHandler})},100)}
setupInitialTabIndex(){this.element.querySelectorAll('.dan-dynamic-island__link').forEach(link=>{link.tabIndex=-1})}
setupKeyboardAccessibility(){this.dynamicIsland.setAttribute('tabindex','0');const islandKeydownHandler=(e)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();this.toggleIsland(!this.isOpen)}};this.dynamicIsland.addEventListener('keydown',islandKeydownHandler);this.eventListeners.push({element:this.dynamicIsland,type:'keydown',handler:islandKeydownHandler})}
setupEventListeners(){const islandClickHandler=(e)=>{if(e.target.closest('.dan-dynamic-island__link')||e.target.closest('.dan-dynamic-island__nav'))return;this.toggleIsland(!this.isOpen)};this.dynamicIsland.addEventListener('click',islandClickHandler);this.eventListeners.push({element:this.dynamicIsland,type:'click',handler:islandClickHandler});const overlayClickHandler=()=>this.toggleIsland(!1);this.overlay.addEventListener('click',overlayClickHandler);this.eventListeners.push({element:this.overlay,type:'click',handler:overlayClickHandler});const keydownHandler=(e)=>{if(e.key==='Escape'&&this.isOpen){this.toggleIsland(!1);this.dynamicIsland.focus()}};document.addEventListener('keydown',keydownHandler);this.eventListeners.push({element:document,type:'keydown',handler:keydownHandler});this.element.querySelectorAll('.dan-dynamic-island__link').forEach(link=>{const linkClickHandler=(e)=>{e.preventDefault();const href=link.getAttribute('href');if(href.startsWith('#')){const targetId=href.slice(1);const targetElement=document.getElementById(targetId);if(targetElement){targetElement.scrollIntoView({behavior:'smooth'});this.toggleIsland(!1);targetElement.focus()}}};const linkKeydownHandler=(e)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();const href=link.getAttribute('href');if(href.startsWith('#')){const targetId=href.slice(1);const targetElement=document.getElementById(targetId);if(targetElement){targetElement.scrollIntoView({behavior:'smooth'});this.toggleIsland(!1);targetElement.focus()}}}};link.addEventListener('click',linkClickHandler);link.addEventListener('keydown',linkKeydownHandler);this.eventListeners.push({element:link,type:'click',handler:linkClickHandler},{element:link,type:'keydown',handler:linkKeydownHandler})})}
destroy(){this.eventListeners.forEach(({element,type,handler})=>{element.removeEventListener(type,handler)});this.eventListeners=[];if(this.animation){this.animation.kill()}
gsap.set([this.dynamicIsland,this.linksContainer,this.overlay],{clearProps:"all"});this.dynamicIsland.classList.remove('open','close');if(this.progressCircle){this.progressCircle.style.strokeDashoffset='';this.progressCircle.classList.remove('animate')}
if(this.percentageText){this.percentageText.textContent='0%'}}}
const dancepad_dynamic_island=()=>{const instances=[];document.querySelectorAll(".dan-dynamic-island").forEach((element)=>{const instance=new DanDynamicIsland(element);instances.push(instance)});DanDynamicIsland.instances=instances}